const scene=new THREE.Scene();scene.background=new THREE.Color('#bfe8ed');scene.fog=new THREE.Fog('#bfe8ed',35,75);const camera=new THREE.PerspectiveCamera(45,1,.1,100);const target=new THREE.Vector3(0,2,0);let angle=.7,elev=.45,distance=20;const hemi=new THREE.HemisphereLight(0xffffff,0x71946a,2.2);scene.add(hemi);const sun=new THREE.DirectionalLight(0xfff0d2,2.4);sun.position.set(8,15,6);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-15,right:15,top:15,bottom:-15});scene.add(sun);
